<?php
require_once __DIR__.'/bootstrap.php'; require_login();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';
 if($action==='add'){$name=trim((string)$_POST['name']);$url=normalize_server_url((string)$_POST['base_url']); if($name&&filter_var($url,FILTER_VALIDATE_URL)){db()->prepare('INSERT INTO servers(name,base_url) VALUES(?,?)')->execute([$name,$url]);$id=(int)db()->lastInsertId();audit_log('server.create','server',$id,$name.' • '.$url);$_SESSION['flash']='Servidor adicionado.';}}
 if($action==='toggle'){$id=(int)$_POST['id'];db()->prepare('UPDATE servers SET is_active=1-is_active WHERE id=?')->execute([$id]);audit_log('server.toggle','server',$id);$_SESSION['flash']='Status atualizado.';}
 if($action==='delete'){$id=(int)$_POST['id'];try{db()->prepare('DELETE FROM servers WHERE id=?')->execute([$id]);audit_log('server.delete','server',$id);$_SESSION['flash']='Servidor removido.';}catch(Throwable $e){$_SESSION['flash']='Servidor em uso por uma ativação; desative em vez de excluir.';}}
 header('Location:servers.php');exit;}
$rows=db()->query('SELECT s.*, (SELECT COUNT(*) FROM activations a WHERE a.server_id=s.id) uses FROM servers s ORDER BY s.id DESC')->fetchAll();$pageTitle='Servidores DNS';include __DIR__.'/partials/header.php';
?>
<?php if($f=$_SESSION['flash']??''){unset($_SESSION['flash']);?><div class="flash"><?=h($f)?></div><?php }?>
<div class="two-col"><section class="card"><h2>Adicionar servidor</h2><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="add"><label>Nome do servidor<input name="name" placeholder="Ex.: Akira Principal" required></label><label>URL / DNS<input type="url" name="base_url" placeholder="https://seu-servidor.com:443" required></label><button class="btn">Salvar servidor</button></form><p class="muted">Cadastre somente servidores e listas para os quais você possui autorização de uso.</p></section>
<section class="card"><h2>Como o app usa o DNS</h2><p class="muted">A ativação associa um dispositivo a um servidor, usuário e senha. O app consulta o painel e usa a API compatível com Xtream Codes do servidor cadastrado.</p><div class="notice">Para HTTP sem HTTPS, o app está preparado para cleartext. Em produção, prefira HTTPS.</div></section></div>
<section class="card"><div class="table-wrap"><table><thead><tr><th>Nome</th><th>URL</th><th>Uso</th><th>Status</th><th>Ações</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="5" class="empty">Nenhum servidor cadastrado.</td></tr><?php endif?><?php foreach($rows as $r):?><tr><td><b><?=h($r['name'])?></b></td><td><span class="code"><?=h($r['base_url'])?></span></td><td><?=$r['uses']?> ativação(ões)</td><td><span class="badge <?=$r['is_active']?'':'off'?>"><?=$r['is_active']?'Ativo':'Inativo'?></span></td><td><div class="actions"><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn dark">Alternar</button></form><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn danger" data-confirm="Remover este servidor?">Excluir</button></form></div></td></tr><?php endforeach?></tbody></table></div></section>
